/* ================= GET STARTED · HOME · ASSIGNED TO ME · PRICING ================= */

/* ---------- Get Started ---------- */
TITLES.getstarted='<b>Get Started</b>';
const GSACT={app:['Install','gsApp'],profile:['Open','gsGo','settings','business'],contacts:['Import contacts','gsImport'],channels:['Connect','gsGo','settings','channels'],stages:['Learn & set','gsStages'],agents:['Set up agents','gsGo','agents'],campaign:['New campaign','gsCamp'],team:['Invite','gsInvite']};
VIEWS.getstarted=()=>{const done=D.gs.filter(s=>s.done).length,pc=Math.round(done/D.gs.length*100);
 return `<div class="page" style="max-width:1080px"><div class="ph"><div><div class="eyebrow">Welcome, Bilal</div><h1 style="font-size:28px">Hello, let’s get started.</h1><p class="sub">Eight short steps and your AI team is working for you. Do them yourself, or press <b>Get it done with AI</b> on any step.</p></div><div class="row">${ring(pc,pc+'%')}<div><b>${done} of ${D.gs.length} done</b><div class="small muted">About ${Math.max(2,(D.gs.length-done)*2)} minutes left</div></div></div></div>
 <div class="card pad" style="margin-bottom:16px;background:var(--ai-soft);border-color:var(--ai-line)"><div class="row nw" style="align-items:flex-start;gap:14px"><span class="orb">${ic('orb',22)}</span><div class="grow stack-s"><h2 style="font-size:17px">Describe your business — Max sets everything up</h2><p class="muted small">Say it or type it: what you sell, where, who your customers are, your hours. Max proposes the stages, agents, campaign and channels, and builds them after you approve.</p>${aiBox('gsIn','e.g. “I run a telecom reseller in Mississauga selling internet and mobile plans, open 9 to 6”','gsAI',{sample:'I run a telecom reseller in Mississauga and Toronto. We sell home internet, TV and mobile plans. Open Monday to Saturday 9 to 6. I want agents to call and text my leads and book installations.'})}</div></div></div>
 <div class="grid" style="grid-template-columns:minmax(0,1fr) 300px;align-items:start"><div class="card gs">${D.gs.map((s,i)=>{const a=GSACT[s.k];return `<div class="gsi ${s.done?'done':''}"><span class="n">${s.done?ic('check',14):i+1}</span><div><div class="tt" style="font-weight:600">${s.l}${s.k==='app'?' <span class="bdg blue">Recommended</span>':''}</div><div class="small muted">${s.d}</div></div><div class="row nw">${s.done?`<span class="bdg good">${ic('check',11)}Done</span>${btn('Open','gsDo',{k:'sm ghost',a:`data-i="${i}"`})}`:`${aiBtn('Get it done with AI','gsAIOne',`data-i="${i}"`,'sm')}${btn(a[0],'gsDo',{k:'sm primary',a:`data-i="${i}"`})}`}</div></div>`}).join('')}</div>
 <div class="stack"><div class="card"><div class="card-h"><h3>Resources</h3></div>${[['play','Watch the 3-minute intro','gsVideo'],['book','Help center & guides','gsHelp'],['headset','Contact support','gsSupport'],['calendar','Book a free onboarding call','gsCall'],['users','Community','gsHelp'],['spark','What’s new','gsHelp']].map(r=>`<button class="lr" data-act="${r[2]}">${ic(r[0],15)}<span class="m">${r[1]}</span>${ic('right',14)}</button>`).join('')}</div>
 <div class="card pad stack-s"><h3>How Crewline works</h3><ol class="small muted" style="margin:0;padding-left:18px;line-height:1.8"><li>Contacts go into <b>folders</b>.</li><li>A <b>campaign</b> picks a folder, channels and agents.</li><li><b>AI agents</b> call, text and email.</li><li>Leads move through <b>stages</b> live.</li><li>Anything AI can’t decide goes to <b>Assigned to me</b>.</li></ol></div></div></div></div>`};
A.gsDo=el=>{const s=D.gs[+el.dataset.i],a=GSACT[s.k];if(a[1]==='gsGo'){if(a[2]==='settings')S.set=a[3];go(a[2])}else A[a[1]](el)};
A.gsApp=()=>openM('installApp');
A.gsImport=()=>{go('contacts');openM('import',{step:1})};
A.gsStages=()=>openM('learnStages');
A.gsCamp=()=>newWizard();
A.gsInvite=()=>openM('invite');
A.gsAIOne=el=>{const s=D.gs[+el.dataset.i];openM('gsAIRun',{i:+el.dataset.i,n:0,lines:GSAI[s.k]||['Done']})};
const GSAI={app:['Prepared the app for your device','Turned on notifications for handovers and bookings'],profile:['Read your website metromobile.example','Filled in business name, industry, hours and products','Set currency to CAD $ and time zone to Toronto'],contacts:['Found your file “mississauga_leads.xlsx” in the upload','Matched 8 of 8 columns automatically','Imported 20,000 people into the folder “Mississauga Leads”','Merged 312 duplicates and queued 4,120 missing emails for filling'],channels:['Reserved a local number (905) 555-0188','Started SMS sender registration for Metro Mobile','Prepared WhatsApp, Messenger and Instagram — you just press Connect'],stages:['Built Outbound stages: New → Contacted → Interested → Pending → Order Booked → Shipped → Installed','Copied them to Inbound','Set “Installed” as the revenue stage'],agents:['Picked Mia (Marketing), Sarah and Robert (Sales), Rhea (Receptionist)','Added your plans and prices to their knowledge','Review score: 86% — ready to go'],campaign:['Created “Mississauga Leads — Outbound”','Text first, call on reply, email after 1 day','Saved as a draft for you to check'],team:['Drafted invites for Ali Raza (Manager) and Front desk','They’ll get handovers from agents']};
M.gsAIRun=m=>{const s=D.gs[m.i];return MS(`${ic('spark',16)} Getting it done with AI`,`<div class="stack-s"><b>${esc(s.l)}</b>${m.lines.map((l,i)=>`<div class="row nw small" style="${i<m.n?'':'color:var(--faint)'}">${i<m.n?`<span class="bdg good" style="width:20px;padding:0;justify-content:center">${ic('check',11)}</span>`:i===m.n?'<span class="spin"></span>':'<span style="width:20px"></span>'}<span>${esc(l)}</span></div>`).join('')}</div>${m.n>=m.lines.length?`<div class="banner ai">${ic('spark',15)}<span>Done. You can check or change anything later.</span></div>`:''}`,m.n>=m.lines.length?btn('Close','close',{k:'primary'}):`<span class="l small muted">Working…</span>`,'n')};
function runGsAI(){const t=setInterval(()=>{if(!S.modal||S.modal.t!=='gsAIRun'){clearInterval(t);return}S.modal.n++;if(S.modal.n>=S.modal.lines.length){clearInterval(t);D.gs[S.modal.i].done=true;renderSide();if(S.view==='getstarted')rr()}renderModal()},650)}
const _gsAIOne=A.gsAIOne;A.gsAIOne=el=>{_gsAIOne(el);runGsAI()};
A.gsAI=()=>{const v=($('#gsIn').value||'').trim();if(!v){toast('Tell Max about your business first — type or press the mic');return}openM('gsPlan',{v})};
M.gsPlan=m=>MS(`${ic('spark',16)} Here’s what Max will set up`,`<div class="cm u"><div class="bb">${esc(m.v)}</div></div><div class="cm x">${MXI()}<div class="bb">Here is my understanding — <b>am I correct?</b><ul><li><b>Business:</b> telecom reseller (internet, TV, mobile) in Mississauga & Toronto</li><li><b>Hours:</b> Mon–Sat, 9 AM – 6 PM</li><li><b>Goal:</b> call and text leads, book installations</li></ul>I’ll set up:<ol><li>Stages: New → Contacted → Interested → Pending → Order Booked → Installed (revenue)</li><li>Agents: Mia (Marketing), Sarah & Robert (Sales), Rhea (Receptionist, books installs)</li><li>Booking: “Fiber installation”, 2 hours, 3 install teams, Mon–Sat 9–6</li><li>A draft campaign for “Mississauga Leads” — text first, call when they reply</li><li>Channels: a local number + SMS registration; WhatsApp ready to connect</li></ol></div></div>`,`${btn('Change something','close',{k:'ghost'})}${btn('Yes, correct — build it','gsBuild',{k:'primary',i:'check'})}`,'w');
A.gsBuild=()=>{openM('gsAIRun',{i:5,n:0,lines:['Created stages (Outbound + Inbound copy)','Set up Mia, Sarah, Robert and Rhea with your prices','Created booking service “Fiber installation”','Created draft campaign “Mississauga Leads — Outbound”','Reserved (905) 555-0188 and started SMS registration']});const t=setInterval(()=>{if(!S.modal||S.modal.t!=='gsAIRun'){clearInterval(t);return}S.modal.n++;if(S.modal.n>=S.modal.lines.length){clearInterval(t);['stages','agents','campaign','channels','profile'].forEach(k=>D.gs.find(s=>s.k===k).done=true);renderSide();if(S.view==='getstarted')rr()}renderModal()},650)};
M.installApp=()=>MS('Install the Crewline web app',`<div class="grid g2"><div class="card pad stack-s"><b>${ic('grid',15)} On a computer</b><ol class="small" style="margin:0;padding-left:18px;line-height:1.8"><li>Open Crewline in Chrome or Edge.</li><li>Click the install icon in the address bar.</li><li>Crewline opens in its own window with notifications.</li></ol></div><div class="card pad stack-s"><b>${ic('phone',15)} On a phone</b><ol class="small" style="margin:0;padding-left:18px;line-height:1.8"><li>Open Crewline in Safari or Chrome.</li><li>Tap Share › “Add to Home Screen”.</li><li>Allow notifications for handovers and bookings.</li></ol></div></div><div class="note">Prototype: installing isn’t possible from this preview.</div>`,`${btn('Done','gsAppDone',{k:'primary'})}`);
A.gsAppDone=()=>{D.gs[0].done=true;closeM();renderSide();rr();toast('Web app step done')};
M.learnStages=()=>MS('How stages work',`<p>Stages show <b>where each lead is</b>. Every campaign follows a set of stages, and <b>AI agents move people automatically</b> as they talk — always following the latest message.</p><div class="row nw" style="overflow-x:auto;padding:4px 0">${D.stages.telecom.out.slice(0,7).map((s,i)=>`<span class="stg" style="height:28px"><i style="background:${s.c}"></i>${s.n}</span>${i<6?ic('right',14):''}`).join('')}</div><div class="grid g3"><div class="card pad stack-s"><b>1 · Criteria</b><span class="small muted">Each stage has sentences like “Customer says OK, go ahead”. When a conversation matches, the lead moves.</span></div><div class="card pad stack-s"><b>2 · Always the latest</b><span class="small muted">“Yes” at 4:30, then “I need time” at 4:35 → the lead moves to Pending.</span></div><div class="card pad stack-s"><b>3 · Review</b><span class="small muted">If the AI isn’t sure, the lead waits in Review for you. It learns from your choice.</span></div></div><div class="card" style="aspect-ratio:16/7;max-width:100%;display:grid;place-items:center;background:var(--subtle)"><div class="stack-s" style="align-items:center">${ic('play',28)}<span class="small muted">Video: Stages in 90 seconds (placeholder)</span></div></div>`,`${btn('Close','close')}${btn('Set my stages','gsStagesGo',{k:'primary'})}`,'w');
A.gsStagesGo=()=>{D.gs.find(s=>s.k==='stages').done=true;go('stages')};
A.gsVideo=()=>openM('video');
M.video=()=>MS('Crewline in 3 minutes',`<div style="aspect-ratio:16/9;max-width:100%;border-radius:10px;background:var(--subtle);display:grid;place-items:center"><div class="stack-s" style="align-items:center">${ic('play',36)}<span class="muted small">Intro video (placeholder in this prototype)</span></div></div>`,btn('Close','close'),'w');
A.gsHelp=()=>toast('Help center opens in a new tab in the real app');
A.gsSupport=()=>openM('support');
M.support=()=>MS('Contact support',`<div class="stack-s">${[['sms','Chat with us','Average reply 2 min, 24/7'],['mail','support@crewline.example','Replies within 4 hours'],['phone','+1 (888) 555-0100','Mon–Fri 8 AM – 8 PM ET']].map(r=>`<div class="lr" style="padding:10px 0">${ic(r[0],16)}<div class="m"><div class="t1">${r[1]}</div><div class="t2">${r[2]}</div></div>${btn('Copy','copy',{k:'xs',a:`data-t="${r[1]}"`})}</div>`).join('')}</div>`,btn('Close','close'),'n');
A.gsCall=()=>toast('Pick a time on the onboarding calendar (opens in the real app)');
A.copy=el=>{const t=el.dataset.t;try{navigator.clipboard.writeText(t).then(()=>toast('Copied'),()=>toast('Select the text and copy it'))}catch(_){toast('Select the text and copy it')}};

/* ---------- Home ---------- */
TITLES.home='<b>Home</b>';
S.home={camps:[],dir:'all',folders:[],panels:{attention:1,kpis:1,bookings:1,activity:1,needs:1,upcoming:1,agents:1,split:1,folders:1,funnel:1,channels:0,costs:0},order:['bookings','split','funnel','folders','channels','costs','activity','needs','upcoming','agents'],kpis:['conv','calls','ans','texts','booked','sales','rev','inbound','cost']};
const HKPI={conv:['Conversations today',412,'+12% vs last Sunday','inbox','<b>412 conversations</b><br>Chat 238 · Calls 121 · Email 53<br>AI handled 94%'],calls:['Calls made',186,'by 6 agents','inbox','<b>186 calls</b><br>Robert 71 · Sarah 58 · Rhea 41 · Sam 16'],ans:['Calls answered',121,'65% answer rate','inbox','<b>121 answered</b><br>Avg. 3m 12s · 9 transferred to a person'],texts:['Texts & emails sent',1930,'312 replies','inbox','<b>1,930 sent</b><br>SMS 1,120 · WhatsApp 402 · Email 408<br>Replies 312 (16%)'],booked:['Appointments & orders booked',38,'+6 vs last Sunday','bookings','<b>38 booked today</b><br>Dental 22 · Installs 11 · Viewings 5<br>Rhea 19 · Robert 8 · Sarah 6 · You 5'],sales:['Sales closed',21,'$14,820 revenue','stages','<b>21 sales</b><br>Installed 14 · Closed 1 · Completed 6'],rev:['Revenue today',14820,'+8% vs avg','reports','<b>$14,820</b><br>Telecom $4,120 · Dental $1,500 · Real estate $9,200'],inbound:['New inbound leads',64,'from ads & landing pages','contacts','<b>64 inbound leads</b><br>Facebook ads 28 · Google ads 17 · Landing page 12 · Calls 7'],cost:['AI & channel cost today',212,'$5.58 per booking','expenses','<b>$212 today</b><br>AI calling $71 · SMS $48 · Voices $28 · Tokens $19 · Other $46'],hand:['Handed to a person',9,'2 waiting','assigned','<b>9 handovers</b><br>7 resolved · 2 waiting in Assigned to me']};
function homeFactor(){let f=1;const h=S.home;if(h.camps.length){const tot=D.campaigns.reduce((a,c)=>a+c.reached,0)||1;f=h.camps.reduce((a,k)=>a+(camp(k)?camp(k).reached:0),0)/tot}if(h.dir!=='all')f*=h.dir==='out'?.58:.42;if(h.folders.length)f*=Math.min(1,h.folders.length*.22);return f}
VIEWS.home=()=>{const h=S.home,f=homeFactor(),v=x=>Math.round(x*f);const P=h.panels;
 const filtLbl=(h.camps.length?h.camps.length+' campaign'+(h.camps.length>1?'s':''):'All campaigns');const foldLbl=h.folders.length?h.folders.length+' folder'+(h.folders.length>1?'s':''):'All lead folders';
 const attn=D.suggestions.concat(D.gs.filter(s=>!s.done).slice(0,2).map(s=>({id:'gs'+s.k,area:'Setup',title:s.l,fix:s.d,go:['getstarted',{}]})));
 const panels={
  bookings:()=>{const vals=[22,25,19,31,28,12,9,30,34,29,36,33,15,38].map(v);const lb=vals.map((_,i)=>dShort(dISO(i-13)));return card('Bookings per day · last 14 days',bars(vals,lb,{unit:'bookings',extra:i=>`AI booked ${Math.round(vals[i]*.8)}`}),'Hover a bar for details')},
  split:()=>{const o=v(1102+790+312),n=v(2310+1240);return card('Inbound vs outbound',`<div class="stack"><div class="hbar"><span>${dirTag('out')}</span><span class="b"><i style="width:${o/(o+n)*100}%;background:var(--out)"></i></span><b class="num">${nf(o)}</b></div><div class="hbar"><span>${dirTag('in')}</span><span class="b"><i style="width:${n/(o+n)*100}%;background:var(--in)"></i></span><b class="num">${nf(n)}</b></div><div class="grid g2 small"><div><div class="muted">Outbound conversion</div><b>11.0%</b></div><div><div class="muted">Inbound conversion</div><b>24.6%</b></div></div></div>`,'Conversations this month')},
  funnel:()=>{const s=D.stages.telecom.out.filter(x=>x.t!=='lost');const base=v(2400);return card('Stage funnel · all campaigns',`<div class="stack-s">${s.map((x,i)=>{const n=Math.round(base*Math.pow(.66,i));return `<div class="hbar" data-tip="<b>${x.n}</b><br>${nf(n)} leads"><span class="trunc"><span class="stg"><i style="background:${x.c}"></i>${x.n}</span></span><span class="b"><i style="width:${n/base*100}%;background:${x.c}"></i></span><b class="num">${nf(n)}</b></div>`}).join('')}</div>`,'<button class="btn link small" data-act="nav" data-v="stages">Open stages</button>')},
  folders:()=>card('Lead folders — how they perform',`<div class="tw"><table class="t compact"><thead><tr><th>Folder</th><th class="r">Leads</th><th class="r">Reached</th><th class="r">Replied</th><th class="r">Booked</th><th class="r">Revenue</th></tr></thead><tbody>${D.folders.filter(x=>!x.grp).slice(0,6).map((x,i)=>{const r=Math.round(x.count*[.55,.42,.3,.71,.38,.2,1,.9][i%8]);return `<tr class="click" data-act="openFolder" data-id="${x.id}"><td>${ic('folder',13)} ${esc(x.name)}</td><td class="r num">${nf(x.count)}</td><td class="r num">${nf(r)}</td><td class="r num">${nf(r*.24)}</td><td class="r num">${nf(r*.05)}</td><td class="r num">${money(r*.05*62)}</td></tr>`}).join('')}</tbody></table></div>`,'Click a folder to open it'),
  channels:()=>card('By channel',`<div class="stack-s">${[['sms',1120,.18],['call',186,.65],['wa',402,.31],['email',408,.09],['msg',96,.44],['ig',61,.52]].map(([k,n,r])=>`<div class="hbar"><span class="row nw">${platIc(k)} ${PL[k].l}</span><span class="b"><i style="width:${r*100}%"></i></span><b class="num">${Math.round(r*100)}%</b></div>`).join('')}</div>`,'Reply / answer rate'),
  costs:()=>card('Spend today',`<div class="stack-s">${D.exp.slice().sort((a,b)=>b.cost-a.cost).slice(0,5).map(e=>`<div class="optrow"><span class="small">${esc(e.n)}</span><b class="num small">${money(e.cost/27,2)}</b></div>`).join('')}</div>`,'<button class="btn link small" data-act="nav" data-v="expenses">Expenses</button>'),
  activity:()=>card(`What your agents are doing right now <span class="bdg good"><span class="dot"></span>Live</span>`,`<div class="feed" id="homefeed">${D.activity.slice(0,7).map(a=>`<div class="fe ${a.nw?'new':''}"><span class="aimark">${ic(a.i,14)}</span><div>${a.text}<div class="small faint">${a.time}</div></div></div>`).join('')}</div>`),
  needs:()=>card(`Assigned to me <span class="bdg bad">${D.assigned.filter(a=>!a.done).length}</span>`,D.assigned.filter(a=>!a.done).slice(0,4).map(a=>`<button class="lr" style="padding:10px 0" data-act="nav" data-v="assigned">${ic(ASK[a.kind][1],15)}<span class="m"><div class="t1 trunc">${esc(a.title)}</div><div class="t2">${ASK[a.kind][0]} · ${a.time}</div></span>${ic('right',14)}</button>`).join('')||empty('Nothing waiting. Your agents have it covered.'),'<button class="btn link small" data-act="nav" data-v="assigned">See all</button>'),
  upcoming:()=>{const L=D.bookings.filter(b=>b.date===dISO(0)&&b.status==='booked').sort((a,b)=>a.start-b.start).slice(0,5);return card('Coming up today',L.map(b=>`<button class="lr" style="padding:8px 0" data-act="bkOpen" data-id="${b.id}" data-tip="<b>${esc(b.who)}</b><br>${esc(b.svc)} with ${esc(b.staff)}<br>${bkTime(b)} · booked by ${esc(byName(b.by))}"><span class="num small" style="width:64px">${bkT(b.start)}</span><span class="m"><div class="t1">${esc(b.who)}</div><div class="t2">${esc(b.svc)} · ${esc(b.staff)}</div></span>${/^[rs]\d/.test(b.by)?`<span class="ai-tag">${ic('spark',10)}${agName(b.by)}</span>`:''}</button>`).join('')||empty('No more bookings today'),'<button class="btn link small" data-act="nav" data-v="bookings">Bookings</button>')},
  agents:()=>{const top=D.agents.filter(a=>a.camps.length).sort((a,b)=>b.score-a.score).slice(0,5);return card('Your AI team today',top.map((a,i)=>`<button class="lr" style="padding:8px 0" data-act="openAgent" data-id="${a.id}"><span class="av sm bot">${ic(AT[a.type].i,12)}</span><span class="m"><div class="t1">${a.name} <span class="small muted">· ${AT[a.type].l}</span></div><div class="t2">${nf(v(a.ws.msgs/30))} messages · ${nf(v(a.ws.calls/30))} calls · ${a.ws.conv}% conversion</div></span><span class="bdg ${a.score>80?'good':'warn'}">${a.score}</span></button>`).join(''),'<button class="btn link small" data-act="nav" data-v="agents">All agents</button>')},
 };
 function card(t,b,r=''){return `<div class="card"><div class="card-h"><h3>${t}</h3><span class="small muted">${r}</span></div><div class="card-b">${b}</div></div>`}
 const L=h.order.filter(k=>P[k]).map(k=>panels[k]());
 return `<div class="page">
 <div class="card hhero" style="padding:28px 28px 20px;margin-bottom:16px"><div class="stack" style="max-width:820px;margin:0 auto;align-items:stretch"><div class="row nw" style="gap:12px"><span class="orb">${ic('orb',22)}</span><div><h1>Good evening, Bilal. What do you want to do?</h1><p class="muted">Talk to Max — it can build campaigns, find people, fix agents or explain any number below.</p></div></div>${aiBox('homeIn','Tell Max what you want — e.g. “Build a campaign for my Mississauga leads”','homeSend',{sample:'Build an outbound campaign for Mississauga Leads by text and call and go live now',voice:1})}<div class="sugg">${[['Build a campaign','Build a new campaign','megaphone'],['Find people in Brooklyn','Find people in Brooklyn','users'],['What should I fix today?','Analyze my campaigns — what should I fix today?','spark'],['Bookings on Sep 23','How many bookings did we have on September 23?','calendar'],['Reduce my costs','How can I reduce my costs?','wallet']].map(q=>`<button data-act="homeQuick" data-q="${esc(q[1])}">${ic(q[2],13)}${q[0]}</button>`).join('')}</div></div></div>
 ${P.attention?`<div class="card" style="margin-bottom:16px;border-color:var(--ai-line)"><div class="card-h"><h3 class="row">${ic('spark',15)}Needs your attention <span class="bdg ai">${attn.length}</span></h3><div class="row">${aiBtn('Let AI finish it with me','homeFixAll','','sm')}</div></div><div>${attn.map(a=>`<div class="lr"><span class="bdg ${a.area==='Setup'?'blue':'warn'}">${a.area}</span><span class="m"><div class="t1">${esc(a.title)}</div><div class="t2">${esc(a.fix)}</div></span>${btn('Open','homeGo',{k:'xs',a:`data-id="${a.id}"`})}${aiBtn('Fix with AI','homeFix',`data-id="${a.id}"`,'xs')}</div>`).join('')}</div></div>`:''}
 <div class="row between" style="margin-bottom:12px"><div class="row">${btn(filtLbl+' '+ic('down',12),'homeCampPick',{k:'sm',i:'megaphone',a:'data-pop'})}${seg([['all','All'],['out','Outbound','out'],['in','Inbound','in']],h.dir,'homeDir')}${btn(foldLbl+' '+ic('down',12),'homeFoldPick',{k:'sm',i:'folder',a:'data-pop'})}${h.camps.length||h.folders.length||h.dir!=='all'?btn('Clear','homeClear',{k:'sm ghost'}):''}</div>${btn('Customize','homeCustom',{k:'sm',i:'grid',t:'Choose what to show and hide'})}</div>
 ${P.kpis?`<div class="kpis" style="margin-bottom:16px">${h.kpis.map(k=>{const x=HKPI[k];return kpi(x[0],k==='rev'||k==='cost'?money(v(x[1])):nf(v(x[1])),x[2],{act:'nav',a:`data-v="${x[3]}"`,t:x[4]})}).join('')}</div>`:''}
 <div class="grid g2" style="align-items:start">${L.join('')}</div></div>`};
A.homeDir=el=>{S.home.dir=el.dataset.v;rr()};
A.homeClear=()=>{S.home.camps=[];S.home.folders=[];S.home.dir='all';rr()};
A.homeCampPick=el=>openPop(el,`<div class="card-h" style="min-height:44px"><h3>Campaigns</h3></div><div style="padding:8px 16px">${D.campaigns.map(c=>`<label class="chk" style="padding:6px 0"><input type="checkbox" data-chg="homeCamp" value="${c.id}" ${S.home.camps.includes(c.id)?'checked':''}>${dirIc(c.dir)}<span>${esc(c.name)}</span></label>`).join('')}</div>`);
A.homeFoldPick=el=>openPop(el,`<div class="card-h" style="min-height:44px"><h3>Lead folders</h3></div><div style="padding:8px 16px">${D.folders.filter(x=>!x.grp).map(f=>`<label class="chk" style="padding:6px 0"><input type="checkbox" data-chg="homeFold" value="${f.id}" ${S.home.folders.includes(f.id)?'checked':''}>${ic('folder',13)}<span>${esc(f.name)} <span class="muted">· ${nf(f.count)}</span></span></label>`).join('')}</div>`);
C.homeCamp=el=>{const a=S.home.camps,i=a.indexOf(el.value);el.checked?i<0&&a.push(el.value):a.splice(i,1);rr()};
C.homeFold=el=>{const a=S.home.folders,i=a.indexOf(el.value);el.checked?i<0&&a.push(el.value):a.splice(i,1);rr()};
A.homeGo=el=>{const a=D.suggestions.find(x=>x.id===el.dataset.id);if(!a){go('getstarted');return}const [v,p]=a.go;if(v==='settings')S.set=p.sec;if(v==='agents'){S.ag.type=p.type;S.ag.sel=p.id}if(v==='contacts')S.ct.tab=p.tab;go(v,p)};
A.homeFix=el=>{const id=el.dataset.id;const i=D.suggestions.findIndex(x=>x.id===id);if(i>=0){const s=D.suggestions[i];D.suggestions.splice(i,1);toast('Max fixed it: '+s.fix,true)}else{const k=id.slice(2);const g=D.gs.find(s=>s.k===k);if(g)g.done=true;toast('Max finished: '+(g?g.l:'setup step'),true)}renderSide();rr()};
A.homeFixAll=()=>{openM('gsAIRun',{i:0,n:0,lines:D.suggestions.map(s=>s.fix).concat(['Finished the remaining setup steps'])});const t=setInterval(()=>{if(!S.modal||S.modal.t!=='gsAIRun'){clearInterval(t);return}S.modal.n++;if(S.modal.n>=S.modal.lines.length){clearInterval(t);D.suggestions.length=0;D.gs.forEach(s=>s.done=true);renderSide();if(S.view==='home')rr()}renderModal()},650)};
A.homeCustom=()=>openM('homeCustom',{p:Object.assign({},S.home.panels),o:S.home.order.slice(),k:S.home.kpis.slice()});
const HPN={attention:'Needs your attention',kpis:'Key numbers',bookings:'Bookings per day',split:'Inbound vs outbound',funnel:'Stage funnel',folders:'Lead folder performance',channels:'By channel',costs:'Spend today',activity:'Live agent activity',needs:'Assigned to me',upcoming:'Coming up today',agents:'Your AI team'};
M.homeCustom=m=>MS('Customize your Home',`<div class="grid g2"><div><div class="lbl" style="margin-bottom:6px">Panels — show, hide and reorder</div><div class="led">${['attention','kpis'].concat(m.o).map((k,i)=>`<div class="led-i"><span class="n">${ic('grip',12)}</span><label class="chk"><input type="checkbox" ${m.p[k]?'checked':''} data-chg="hcP" data-k="${k}">${HPN[k]}</label><span class="row nw">${i>1?`${iconBtn('up','hcMove','Move up',`data-k="${k}" data-d="-1"`,'xs')}${iconBtn('dn','hcMove','Move down',`data-k="${k}" data-d="1"`,'xs')}`:''}</span><span></span></div>`).join('')}</div></div>
 <div><div class="lbl" style="margin-bottom:6px">Key numbers</div><div class="led">${Object.keys(HKPI).map(k=>`<div class="led-i"><span class="n"></span><label class="chk"><input type="checkbox" ${m.k.includes(k)?'checked':''} data-chg="hcK" data-k="${k}">${HKPI[k][0]}</label><span></span><span></span></div>`).join('')}</div><div class="note" style="margin-top:10px">Tip: ask Max “show only bookings and revenue on my home” and it does this for you.</div></div></div>`,`${btn('Reset','hcReset',{k:'ghost'})}${btn('Save','hcSave',{k:'primary'})}`,'w');
C.hcP=el=>{S.modal.p[el.dataset.k]=el.checked?1:0};
C.hcK=el=>{const a=S.modal.k,k=el.dataset.k,i=a.indexOf(k);el.checked?i<0&&a.push(k):a.splice(i,1)};
A.hcMove=el=>{const o=S.modal.o,i=o.indexOf(el.dataset.k),j=i+ +el.dataset.d;if(j<0||j>=o.length)return;[o[i],o[j]]=[o[j],o[i]];renderModal()};
A.hcSave=()=>{S.home.panels=S.modal.p;S.home.order=S.modal.o;S.home.kpis=S.modal.k;closeM();rr();toast('Home updated')};
A.hcReset=()=>{Object.assign(S.modal,{p:{attention:1,kpis:1,bookings:1,activity:1,needs:1,upcoming:1,agents:1,split:1,folders:1,funnel:1,channels:0,costs:0}});renderModal()};

/* ---------- Assigned to me ---------- */
TITLES.assigned='<b>Assigned to me</b>';
const ASK={hand:['Handover','hand'],book:['Appointment request','calendar'],stage:['Choose a stage','kanban'],angry:['Upset customer','alert'],qual:['Unclear qualification','query'],number:['New number found','phone']};
S.asg={tab:'all'};
VIEWS.assigned=()=>{const L=D.assigned.filter(a=>!a.done&&(S.asg.tab==='all'||a.kind===S.asg.tab));const cnt=k=>D.assigned.filter(a=>!a.done&&(k==='all'||a.kind===k)).length;
 return `<div class="page" style="max-width:1080px"><div class="ph"><div><h1>Assigned to me</h1><p class="sub">Everything the AI couldn’t decide on its own, or that needs a person. You’re also notified here and inside the chat. Once you decide, the item disappears and the AI learns from it.</p></div>${btn('Notification settings','nav',{k:'sm',i:'bell',a:'data-v="settings"'})}</div>
 ${tabs([['all','All',null,cnt('all')],['hand','Handovers',null,cnt('hand')],['book','Appointment requests',null,cnt('book')],['stage','Choose a stage',null,cnt('stage')],['qual','Qualification',null,cnt('qual')],['angry','Upset customers',null,cnt('angry')],['number','Data updates',null,cnt('number')]],S.asg.tab,'asgTab')}
 <div class="stack">${L.map(a=>{const c=a.cid?byId(a.cid):null,cp=a.camp?camp(a.camp):null;const k=ASK[a.kind];return `<div class="card"><div class="card-b stack-s"><div class="row between"><div class="row"><span class="bdg ${a.kind==='angry'?'bad':a.kind==='book'?'blue':'warn'}">${ic(k[1],12)}${k[0]}</span>${cp?`<button class="bdg line" data-act="nav" data-v="campaign" data-p='{"id":"${cp.id}"}'>${dirIc(cp.dir)} ${esc(cp.name)}</button>`:''}</div><span class="small faint">${a.time}</span></div>
  <h3 style="font-size:15px">${esc(a.title)}</h3><p class="muted">${esc(a.desc)}</p>${c?`<div class="row small"><span class="muted">Contact:</span><button class="lnk" data-act="openContact" data-id="${c.id}">${esc(cname(c))}</button><span class="muted">· ${c.phone}</span></div>`:''}
  ${a.rec?`<div class="callc" style="width:100%"><div class="wave"><button class="pl" data-act="toast" data-m="Playing call recording (prototype)" aria-label="Play">${ic('play',12)}</button>${waveSvg()}</div><div class="small"><b>AI summary:</b> ${esc(a.desc)}</div></div>`:''}
  <div class="row" style="margin-top:4px">${asgActions(a)}</div></div></div>`}).join('')||`<div class="card">${empty('All clear — nothing needs you right now.')}</div>`}</div></div>`};
function asgActions(a){const open=a.convo?btn('Open chat','openConvo',{k:'sm',i:'sms',a:`data-id="${a.convo}"`}):'';
 if(a.kind==='hand')return `${open}${btn('Take over','asgTake',{k:'sm primary',i:'hand',a:`data-id="${a.id}"`})}${sel(D.team.map(t=>t[0]),'Ali Raza',`data-chg="asgAssign" data-id="${a.id}" aria-label="Assign to"`,'sm auto')}${btn('Mark done','asgDone',{k:'sm ghost',a:`data-id="${a.id}"`})}`;
 if(a.kind==='book')return `${open}${btn('Assign to receptionist (Rhea)','asgRecep',{k:'sm primary',i:'bell',a:`data-id="${a.id}"`})}${btn('Handle manually','asgBook',{k:'sm',i:'calendar',a:`data-id="${a.id}"`})}`;
 if(a.kind==='stage'){const c=byId(a.cid),cp=camp(a.camp);return `${sel(stagesOf(cp).map(s=>s.n),c?c.stage:'',`id="asgSt-${a.id}" aria-label="Stage"`,'sm auto')}${btn('Save stage','asgStage',{k:'sm primary',a:`data-id="${a.id}"`})}${btn('Open transcript','toast',{k:'sm',a:'data-m="Transcript opened (prototype)"'})}`}
 if(a.kind==='qual')return `${open}${btn('Mark qualified','asgQual',{k:'sm primary',a:`data-id="${a.id}" data-v="Qualified"`})}${btn('Not qualified','asgQual',{k:'sm',a:`data-id="${a.id}" data-v="Not qualified"`})}${aiBtn('Ask another question','asgQual',`data-id="${a.id}" data-v="ask"`,'sm')}`;
 if(a.kind==='angry')return `${btn('Call back now','callNum',{k:'sm primary',i:'phone',a:`data-num="(647) 555-0122"`})}${btn('Assign to Finance (Quinn)','asgDone',{k:'sm',a:`data-id="${a.id}" data-m="Assigned to Quinn (Finance) — she’ll refund and follow up"`})}${btn('Mark done','asgDone',{k:'sm ghost',a:`data-id="${a.id}"`})}`;
 if(a.kind==='number')return `${btn('Update to (905) 555-0162','asgNum',{k:'sm primary',a:`data-id="${a.id}"`})}${btn('Keep old number','asgDone',{k:'sm',a:`data-id="${a.id}"`})}`;
 return ''}
const waveSvg=()=>{let r='';for(let i=0;i<60;i++){const h=4+Math.abs(Math.sin(i*1.7)*Math.cos(i*.37))*20;r+=`<rect x="${i*5}" y="${13-h/2}" width="3" height="${h}" rx="1.5"/>`}return `<svg viewBox="0 0 300 26" preserveAspectRatio="none" aria-hidden="true">${r}</svg>`};
function asgClose(id,msg,ai){const a=D.assigned.find(x=>x.id===id);a.done=true;renderTop();if(S.view==='assigned')rr();toast(msg,ai)}
A.asgTab=el=>{S.asg.tab=el.dataset.v;rr()};
A.asgDone=el=>asgClose(el.dataset.id,el.dataset.m||'Marked done');
A.asgTake=el=>{const a=D.assigned.find(x=>x.id===el.dataset.id);const v=D.convos.find(c=>c.id===a.convo);if(v){v.human=true;v.needs=false;v.items.push(ev('sys','You took over · '+agName(v.agent)+' is paused for this person','now'))}asgClose(a.id,'You’re handling it now');if(v){S.ib.id=v.id;go('inbox')}};
C.asgAssign=el=>asgClose(el.dataset.id,'Assigned to '+el.value+' — they’ve been notified');
A.asgRecep=el=>{const a=D.assigned.find(x=>x.id===el.dataset.id);const v=D.convos.find(c=>c.id===a.convo);if(v){v.items=v.items.filter(i=>i.t!=='inchat');v.items.push(ev('sys','Rhea (Receptionist) joined to book the appointment','now'),m('o','r1','Hi Maria, I’m Rhea from Metro Mobile. I can book your installer Saturday between 9 and 11 AM. Shall I lock that in?','now','delivered'))}asgClose(a.id,'Rhea is booking it — you’ll see it in Bookings',true)};
A.asgBook=el=>{const a=D.assigned.find(x=>x.id===el.dataset.id);openBooking({camp:a.camp==='k1'?'k1':a.camp,who:cname(byId(a.cid)),cid:a.cid,svc:'Fiber installation',asg:a.id})};
A.asgStage=el=>{const a=D.assigned.find(x=>x.id===el.dataset.id);const v=$('#asgSt-'+a.id).value;const c=byId(a.cid);if(c)c.stage=v;asgClose(a.id,`Stage set to ${v}. The AI learned from this — it won’t ask for similar cases.`,true)};
A.asgQual=el=>{const a=D.assigned.find(x=>x.id===el.dataset.id);const v=el.dataset.v;if(v==='ask'){asgClose(a.id,'Ellie will ask for the postal code another way',true);return}const c=byId(a.cid);if(c)c.stage=v==='Qualified'?'Qualified':'Not qualified';asgClose(a.id,'Saved — '+v+'. The AI learned from this.',true)};
A.asgNum=el=>{const a=D.assigned.find(x=>x.id===el.dataset.id);const c=byId(a.cid);c.phone='(905) 555-0162';c.noReply=0;asgClose(a.id,'Number updated — Ahmed is back in the campaign')};

/* ---------- Pricing ---------- */
TITLES.pricing='<b>Plans & pricing</b>';
S.price={yr:false};
VIEWS.pricing=()=>{const P=[['Starter',49,'For one business trying AI agents',['1 business','3 AI agents','2,000 contacts','500 AI call minutes','Inbox, Contacts, Stages','Email support']],['Growth',299,'For growing teams — most popular',['3 businesses','All 18 default agents + 10 custom','50,000 contacts','5,000 AI call minutes','Bookings & receptionist','Max assistant','Reports']],['Pro',799,'For multi-location businesses',['10 businesses','Unlimited agents','250,000 contacts','20,000 AI call minutes','Voice cloning','HTTP actions & API','Priority support']],['Enterprise',null,'For agencies and large teams',['Unlimited businesses','White-label','Custom AI models','SSO & audit log','Dedicated success manager','Custom contracts']]];
 return `<div class="page" style="max-width:1180px"><div class="ph" style="justify-content:center;text-align:center;flex-direction:column;align-items:center"><h1>Plans & pricing</h1><p class="sub">Placeholder — final packages will be decided at the end of development.</p>${seg([['m','Monthly'],['y','Yearly · save 20%']],S.price.yr?'y':'m','priceYr')}</div>
 <div class="plans">${P.map((p,i)=>`<div class="card plan ${i===1?'hot':''}">${i===1?'<span class="bdg blue" style="align-self:flex-start">Your plan</span>':''}<h2>${p[0]}</h2><div class="pr">${p[1]==null?'Custom':money(S.price.yr?p[1]*.8:p[1])}<span class="small muted" style="font-weight:400">${p[1]==null?'':' / month'}</span></div><p class="small muted">${p[2]}</p><ul>${p[3].map(x=>`<li>${x}</li>`).join('')}</ul><span class="grow"></span>${btn(i===1?'Current plan':p[1]==null?'Talk to sales':'Choose '+p[0],'toast',{k:i===1?'':'primary',a:`data-m="Plan changes happen in Settings › Billing (prototype)"`,d:i===1})}</div>`).join('')}</div>
 <p class="small muted" style="text-align:center;margin-top:16px">All plans: pay-as-you-go usage for calls, texts, voices and data at cost + a small margin. See Expenses for your usage.</p></div>`};
A.priceYr=el=>{S.price.yr=el.dataset.v==='y';rr()};
